def resumen(*ventas):
    """Devuelve cantidad, total y promedio de las ventas."""
    if not ventas:
        return 0, 0, 0
    total = sum(ventas)
    return len(ventas), total, total / len(ventas)


cantidad, total, media = resumen(120, 80, 45)
print(f"{cantidad} ventas | total {total} | media {media:.2f}")

dia = [120, 80, 45]
print(resumen(*dia))

